parameters.jsCode:
const content = $json.message.content;

const data = JSON.parse(content);

return [
  {
    json: {
      tool: data.tool,
      memory_action: data.memory_action,
      memory_content: data.memory_content,
      question: $('user3').first().json.question
    }
  }
];

const text =$('question').first().json.question;
const vector = $input.first().json.embeddings[0]

return [
  {
    json: {
      id: Date.now(),
      text: text,
      vector: vector,
    },
  },
];

const data = $json;
const result = data.result?.[0];

if (!result) {
  return [
    {
      json: {
        found: false,
        signal: "not_found"
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      signal: "found",
      id: result.id,
      score: result.score,
      text: result.payload?.text || ""
    }
  }
];

