parameters.jsCode:
const data = $json;
const response =$input.first().json.response;

if (data.signal === "already_exists"){
  return [{
    json: {
      signal: "already_exists",
      success: false,
      response: "This information is already stored in memory."
    }
  }];
}else if(data.signal === "save"){
  return [{
    json: {
      signal: "save",
      success: true,
      response: "The information has been saved successfully."
    }
  }];
}else if(data.signal === "deleted"){
   return [{
    json: {
      signal: "deleted",
      success: true,
      response: "The information has been deleted successfully."
    }
  }];
}else if(data.signal === "no_data"){
   return [{
    json: {
      signal: "not_found",
      success: true,
      response: "I do not have the data you want to delete."
    }
  }];
}else if(data.signal === "found"){
   return [{
    json: {
      signal: "found",
      success: true,
      response:$input.first().json.text 
    }
  }];
}else if(data.signal === "data_not_found"){
   return [{
    json: {
      signal: "data_not_found",
      success: true,
      response:"Sorry, I do not have this data."
    }
  }];
}else if(data.signal === "agent"){
   return [{
    json: {
      signal: "agent",
      success: true,
      response:$input.first().json.text
    }
  }];
}

return [
  {
    json: {
      signal: "already_exists",
      success: false,
      response: "This information is already stored in memory."
    }
  }
];

const vector = $('Insert Embedding').first().json.embeddings[0];

const content =$('insert Target').first().json.insert_query;

return [
  {
    json: {

      vector: vector,
      text: content
    }
  }
];

const qdrant = $json;

return [
  {
    json: {

      success: qdrant.status === "ok",
      signal:
        qdrant.status === "ok"
          ? "deleted"
          : "The information could not be deleted.",
      result: qdrant.result
    }
  }
];

const data = $json;

if (
  data.status === "ok" &&
  data.result?.status === "acknowledged"
) {
  return [
    {
      json: {
        signal: "save",
        success: true,
        response: "saved"
      }
    }
  ];
}

return [];

return [
  {
    json: {
      signal: "agent",
      success: true,
      text: $input.first().json.output
    }
  }
];
